def _tier_model(tier):
    """Resolve tier -> familia, validando que o id existe (fallback declarado do tier 'max')."""
    t = POLICY["tiers"][tier]
    fam = t["model"]
    if fam not in MODEL_ID and t.get("fallback") in MODEL_ID:
