def _heterogeneous(author):
    """Degrau 2 da escada (ADR-078/018): modelo DIFERENTE do autor. Caminha max->balanced->economy
    pulando o modelo do autor e indisponiveis; esgotado -> degrau 3 (mesmo modelo, fresh, DECLARADO)."""
    seen = []
    for tier in ("max", "balanced", "economy"):
        for fam in POLICY["tiers"][tier]["chain"]:
            if fam not in seen:
                seen.append(fam)
    for fam in seen:
        if fam != author and _available(fam):
            return fam, ""
    return author, (" [DEGRAU 3 da escada: nenhum modelo distinto disponivel -> mesmo modelo em "
                    "contexto fresh — DECLARAR no veredito, nunca fingir heterogeneidade]")

